// Normalise messy inbound payloads into one shape.
const input = $json.body || $json;
const c = input.contact || input;
const email = String(c.email || c.email_address || '').trim().toLowerCase();
const phone = String(c.phone || c.phone_number || '').replace(/[^\d+]/g, '');
if (!email && !phone) throw new Error('Lead needs an email or phone');
const aliases = { fb: 'facebook_ads', facebook: 'facebook_ads', land: 'landing_page', web: 'website_form' };
const rawSource = String(input.source || input.utm_source || 'website_form').toLowerCase();
const budgetNums = String(input.budget || input.budget_usd || '').replace(/,/g, '').match(/\d+(?:\.\d+)?\s*[km]?/gi) || [];
let budget = null;
if (budgetNums.length) {
  const toNum = (s) => { const n = parseFloat(s); return /k/i.test(s) ? n * 1000 : /m/i.test(s) ? n * 1e6 : n; };
  budget = budgetNums.length > 1 ? Math.round((toNum(budgetNums[0]) + toNum(budgetNums[1])) / 2) : toNum(budgetNums[0]);
}
return [{ json: {
  id: Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10),
  created_at: new Date().toISOString(),
  source: aliases[rawSource] || rawSource,
  contact: { name: c.name || c.full_name || 'unknown', email, phone, company: c.company || c.company_name || '' },
  message: String(input.message || input.comments || '').slice(0, 8000),
  budget_usd: budget,
  timeline: input.timeline || input.timeframe || null,
  status: 'received',
}}];

