// Guardrails: accept only well-formed JSON from the model, clamp the score and
// keep tier/score consistent. If anything is off, fall back to a rules score.
const lead = $('Normalize lead').first().json;
let raw = {};
try {
  const content = $json.choices?.[0]?.message?.content ?? $json.content ?? '{}';
  raw = JSON.parse(String(content).replace(/^\`\`\`json/i, '').replace(/\`\`\`$/, ''));
} catch (e) { raw = {}; }

const score = Math.max(0, Math.min(100, Math.round(Number(raw.score) || 0)));
let fallback = score === 0;
// Deterministic backstop so a broken model response never blocks the pipeline.
if (fallback) {
  const text = (lead.message + ' ' + lead.contact.company).toLowerCase();
  const buying = ['need','looking for','quote','proposal','rfp','budget','evaluating'].filter(t => text.includes(t)).length;
  const urgent = ['asap','urgent','deadline','this week','within','quarter'].filter(t => text.includes(t)).length;
  let s = 12 + Math.min(24, buying * 4) + urgent * 10 + (lead.budget_usd >= 5000 ? 16 : 0) + (lead.contact.company ? 6 : 0);
  raw = {
    score: s,
    intent: buying ? 'estimated from rules' : 'unclear',
    urgency: urgent ? 'this_week' : 'unknown',
    budget_fit: lead.budget_usd == null ? 'unknown' : lead.budget_usd >= 5000 ? 'in_range' : 'below_range',
    reasons: ['LLM unavailable — deterministic fallback used.'],
    missing_info: lead.budget_usd ? [] : ['budget'],
    flags: ['llm_unavailable'],
    next_action: s >= 70 ? 'Call within 15 minutes.' : 'Review manually.',
    draft_reply: s >= 40 ? 'Hi ' + (lead.contact.name.split(' ')[0] || 'there') + ', thanks for reaching out. What does your ideal start date look like?' : '',
  };
}
const tier = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
return [{ json: { ...lead, qualification: { ...raw, score, tier, engine: fallback ? 'rules' : 'llm', qualified_at: new Date().toISOString() } } }];
